def _validate_request_payload(payload):
    """Validate and return a request payload.

    Request payloads must be dictionaries with string keys. Keeping this logic
    separate from request processing makes the validation rules explicit and
    ensures every payload is checked before it reaches ``process``.
    """
    if not isinstance(payload, dict):
        raise TypeError("data must be a dictionary")

    if not all(isinstance(key, str) for key in payload.keys()):
        raise TypeError("data keys must be strings")

    return payload


def handle_request(data):
    """Validate an incoming API request payload before processing it."""
    payload = _validate_request_payload(data)
    return process(payload)

